function renderKpis() {
  const k = DATA.kpis;
  const items = [
    ['遊戲數', fmt.format(k.games), 'Mar-May 資料集內遊戲總量'],
    ['供應商數', fmt.format(k.providers), '內容供給廣度'],
    ['總投注（萬）', wan(k.totalBetWan), 'Mar-May 消費規模'],
    ['GGR（萬）', wan(k.ggrWan), '商業價值'],
    ['加權 RTP', pct2(k.weightedRtp), '按投注加權後的派彩比例'],
    ['前三大供應商占比', pct(k.top3ProviderShare), '供應商集中度'],
    ['前五大遊戲占比', pct(k.top5GameShare), '遊戲集中度'],
    ['總 Spin 數', fmt.format(k.totalSpins), '遊玩互動量'],
  ];
  document.querySelector('#kpiGrid').innerHTML = items.map(([label, value, note]) => `
    <article class="kpi"><label>${label}</label><strong>${value}</strong><span>${note}</span></article>
  `).join('');
}

